module government_graph (\n  input clk, rst_n, start,\n  input [3:0] n,\n  input [1:0] k,\n  input [2:0] gov0, gov1, gov2,\n  input [4:0] m,\n  input [95:0] edges,\n  output reg [15:0] result,\n  output reg done\n);\n  // State declarations with explicit widths\n  localparam [3:0] IDLE              = 4'd0;\n  localparam [3:0] INIT              = 4'd1;\n  localparam [3:0] BUILD_ADJ         = 4'd2;\n  localparam [3:0] PROCESS_GOV_START = 4'd3;\n  localparam [3:0] BFS_LOOP          = 4'd4;\n  localparam [3:0] BFS_CHECK_NEIGH   = 4'd5;\n  localparam [3:0] CALCULATE_NON_GOV = 4'd6;\n  localparam [3:0] CALCULATE_GOV_EDGES = 4'd7;\n  localparam [3:0] CALCULATE_RESULT  = 4'd8;\n  localparam [3:0] DONE_STATE        = 4'd9;\n  \n  reg [3:0] state;\n  reg [7:0] adj [0:7];  // 8x8 adjacency matrix (packed)\n  reg [7:0] visited;\n  reg [3:0] gov_component_sizes [0:2];  // Size per gov\n  reg [3:0] total_gov_nodes;\n  reg [1:0] index;\n  reg [2:0] queue [0:7];    // BFS queue\n  reg [2:0] head, tail;\n  reg [3:0] size;\n  reg [2:0] current_u;\n  reg [2:0] v_counter;\n  reg [4:0] i_edge;\n  reg [3:0] non_gov_count;\n  reg [3:0] max_gov;\n  reg [15:0] total_edges;\n  reg [1:0] i_calc;\n  reg [7:0] temp1, temp2;\n  \n  always @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n      // Initialize ALL registers\n      state <= IDLE;\n      done <= 1'b0;\n      result <= 16'd0;\n      visited <= 8'd0;\n      adj[0] <= 8'd0; adj[1] <= 8'd0; adj[2] <= 8'd0; adj[3] <= 8'd0;\n      adj[4] <= 8'd0; adj[5] <= 8'd0; adj[6] <= 8'd0; adj[7] <= 8'd0;\n      gov_component_sizes[0] <= 4'd0; gov_component_sizes[1] <= 4'd0; gov_component_sizes[2] <= 4'd0;\n      total_gov_nodes <= 4'd0;\n      index <= 2'd0;\n      head <= 3'd0; tail <= 3'd0; size <= 4'd0;\n      current_u <= 3'd0; v_counter <= 3'd0;\n      i_edge <= 5'd0;\n      non_gov_count <= 4'd0; max_gov <= 4'd0; total_edges <= 16'd0; i_calc <= 2'd0;\n    end \n    else begin\n      case (state)\n        IDLE: begin\n          done <= 1'b0;\n          if (start) state <= INIT;\n        end\n        \n        INIT: begin\n          visited <= 8'd0;\n          adj[0] <= 8'd0; adj[1] <= 8'd0; adj[2] <= 8'd0; adj[3] <= 8'd0;\n          adj[4] <= 8'd0; adj[5] <= 8'd0; adj[6] <= 8'd0; adj[7] <= 8'd0;\n          gov_component_sizes[0] <= 4'd0; gov_component_sizes[1] <= 4'd0; gov_component_sizes[2] <= 4'd0;\n          total_gov_nodes <= 4'd0;\n          index <= 2'd0;\n          i_edge <= 5'd0;\n          state <= BUILD_ADJ;\n        end\n        \n        BUILD_ADJ: begin\n          if (i_edge < m) begin\n            if (edges[6*i_edge +: 3] < n && edges[6*i_edge + 3 +: 3] < n && \n                edges[6*i_edge +: 3] != edges[6*i_edge + 3 +: 3]) begin\n              adj[edges[6*i_edge +: 3]][edges[6*i_edge + 3 +: 3]] <= 1'b1;\n              adj[edges[6*i_edge + 3 +: 3]][edges[6*i_edge +: 3]] <= 1'b1;\n            end\n            i_edge <= i_edge + 5'd1;\n          end\n          else state <= PROCESS_GOV_START;\n        end\n        \n        PROCESS_GOV_START: begin\n          if (index < k) begin\n            case (index)\n              2'd0: current_u <= gov0;\n              2'd1: current_u <= gov1;\n              2'd2: current_u <= gov2;\n            endcase\n            if (!visited[current_u]) begin\n              queue[0] <= current_u;\n              head <= 3'd0;\n              tail <= 3'd1;\n              visited[current_u] <= 1'b1;\n              size <= 4'd0;\n              state <= BFS_LOOP;\n            end\n            else begin\n              gov_component_sizes[index] <= 4'd0;\n              index <= index + 2'd1;\n              state <= PROCESS_GOV_START;\n            end\n          end\n          else state <= CALCULATE_NON_GOV;\n        end\n        \n        BFS_LOOP: begin\n          if (head < tail) begin\n            current_u <= queue[head];\n            head <= head + 3'd1;\n            size <= size + 4'd1;\n            v_counter <= 3'd0;\n            state <= BFS_CHECK_NEIGH;\n          end\n          else begin\n            gov_component_sizes[index] <= size;\n            total_gov_nodes <= total_gov_nodes + size;\n            index <= index + 2'd1;\n            state <= PROCESS_GOV_START;\n          end\n        end\n        \n        BFS_CHECK_NEIGH: begin\n          if (v_counter < n) begin\n            if (adj[current_u][v_counter] && !visited[v_counter]) begin\n              visited[v_counter] <= 1'b1;\n              queue[tail] <= v_counter;\n              tail <= tail + 3'd1;\n            end\n            v_counter <= v_counter + 3'd1;\n          end\n          else state <= BFS_LOOP;\n        end\n        \n        CALCULATE_NON_GOV: begin\n          non_gov_count <= n - total_gov_nodes;\n          max_gov <= gov_component_sizes[0];\n          if (k > 2'd1 && gov_component_sizes[1] > max_gov) max_gov <= gov_component_sizes[1];\n          if (k > 2'd2 && gov_component_sizes[2] > max_gov) max_gov <= gov_component_sizes[2];\n          total_edges <= 16'd0;\n          i_calc <= 2'd0;\n          state <= CALCULATE_GOV_EDGES;\n        end\n        \n        CALCULATE_GOV_EDGES: begin\n          if (i_calc < k) begin\n            if (gov_component_sizes[i_calc] != max_gov) begin\n              temp1 = gov_component_sizes[i_calc] * (gov_component_sizes[i_calc] - 4'd1);\n              total_edges <= total_edges + {8'd0, temp1[7:1]};  // temp1/2 (integer division)\n            end\n            i_calc <= i_calc + 2'd1;\n          end\n          else begin\n            temp2 = (non_gov_count + max_gov) * (non_gov_count + max_gov - 4'd1);\n            total_edges <= total_edges + {8'd0, temp2[7:1]};  // temp2/2\n            state <= CALCULATE_RESULT;\n          end\n        end\n        \n        CALCULATE_RESULT: begin\n          result <= total_edges - {11'd0, m};\n          state <= DONE_STATE;\n        end\n        \n        DONE_STATE: begin\n          done <= 1'b1;\n          state <= IDLE;\n        end\n        \n        default: state <= IDLE;\n      endcase\n    end\n  end\nendmodule